import type { LegalTranslations } from '../components/LegalDocument';

function defineTranslations(entries: Record<string, string>): LegalTranslations {
  return Object.fromEntries(
    Object.entries(entries).map(([korean, english]) => [korean.replace(/\s+/g, ''), english]),
  );
}

